      "overviewMal": "സോഷ്യോളജിക്കൽ വീക്ഷണങ്ങളും (സ്ട്രക്ചറൽ ഫങ്ഷണലിസം, കോൺഫ്ലിക്റ്റ് തിയറി, സിംബോളിക് ഇന്ററാക്ഷനിസം, എത്‌നോമെത്തഡോളജി) ശാസ്ത്രീയ ഗവേഷണ രീതികളും വിശദീകരിക്കുന്നു. ക്വാണ്ടിറ്റേറ്റീവ്, ക്വാളിറ്റേറ്റീവ് രീതികൾ, പങ്കാളിത്ത നിരീക്ഷണം, ചോദ്യാവലി, സാമ്പിളിംഗ്, വെർസ്റ്റെഹെൻ, ഗവേഷണ ധാർമ്മികത എന്നിവ ഉൾക്കൊള്ളുന്നു.",
