      "examTakeaways": [
        {
          "en": "Remember the distinction: Cooperation, Accommodation, and Assimilation bring people together; Competition and Conflict divide.",
          "mal": "സഹകരണവും അക്കൊമഡേഷനും ആളുകളെ ഒന്നിപ്പിക്കുമ്പോൾ മത്സരവും സംഘർഷവും ഭിന്നതയുണ്ടാക്കുന്നു."
        },
        {
          "en": "Assimilation is slow, unconscious, and permanent, whereas accommodation is conscious and often temporary.",
          "mal": "അസിമിലേഷൻ സാവധാനമുള്ളതും ശാശ്വതവുമായ മാറ്റമാണ്, അക്കൊമഡേഷൻ ബോധപൂർവ്വമായ താൽക്കാലിക ക്രമീകരണമാണ്."
        }
      ]
