          "definition": "The lifelong process by which individuals internalize societal culture and develop their human potential.",
          "definitionMal": "വ്യക്തികൾ സാമൂഹിക സംസ്കാരം ഉൾക്കൊണ്ട് തങ്ങളുടെ വ്യക്തിത്വം വികസിപ്പിച്ചെടുക്കുന്ന ജീവിതകാല പ്രക്രിയ."
