      "overviewMal": "അടിസ്ഥാന മനുഷ്യ ആവശ്യങ്ങൾ നിറവേറ്റുന്നതിനായി സമൂഹം ചിട്ടപ്പെടുത്തിയിട്ടുള്ള സാമൂഹിക സ്ഥാപനങ്ങളെക്കുറിച്ചുള്ള (Social Institutions) വിശദമായ പഠനം. നിർവ്വചനം, സവിശേഷതകൾ, മാനിഫെസ്റ്റ്-ലേറ്റന്റ് ധർമ്മങ്ങൾ, അഞ്ച് പ്രധാന സ്ഥാപനങ്ങൾ (കുടുംബം, വിവാഹം, ബന്ധുത്വം, സമ്പദ്‌വ്യവസ്ഥ, രാഷ്ട്രീയം, മതം) എന്നിവ വിശകലനം ചെയ്യുന്നു.",
